ALTER TABLE ISTANZEEVENTI MODIFY IDEVENTO NUMBER(10);
ALTER TABLE ISTANZEEVENTI ADD SOFTWARE VARCHAR2(2);
ALTER TABLE ISTANZEEVENTI ADD CONSTRAINT FK_IEVENTI_SOFTWARE FOREIGN KEY (SOFTWARE) REFERENCES SOFTWARE(CODICE);
